<script setup lang="ts">import { computed } from 'vue'; import { formatMoney } from '../../utils/formatters'; import type { ExpenseSummary, FinancialSummary } from '../../types'; const props = defineProps<{ summary: ExpenseSummary & { financial?: FinancialSummary }; financial?: FinancialSummary }>(); const cards = computed(() => { const financial = props.financial ?? props.summary.financial; return [...(financial ? [{ label: 'Revenue', value: formatMoney(financial.total_revenue) }, { label: 'Total cost', value: formatMoney(financial.total_cost) }, { label: financial.is_loss ? 'Net loss' : 'Net profit', value: formatMoney(financial.net_profit) }] : []), { label: 'Total expenses', value: formatMoney(props.summary.total_amount) }, { label: 'Transactions', value: String(props.summary.transaction_count) }, ...(props.summary.average_amount ? [{ label: 'Average expense', value: formatMoney(props.summary.average_amount) }] : []), ...(props.summary.largest_amount ? [{ label: 'Largest expense', value: formatMoney(props.summary.largest_amount) }] : [])]; });</script>
<template><div class="grid min-w-0 gap-4 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-6"><article v-for="card in cards" :key="card.label" class="card min-w-0"><p class="text-sm text-slate-500">{{ card.label }}</p><p class="mt-2 break-words text-xl font-semibold tabular-nums">{{ card.value }}</p></article></div></template>
